class ReportHttpTest {
 private static final UUID CORRELATION=UUID.fromString("10000000-0000-4000-8000-000000000110");
 @Test void actualHttpEnforcesSignedAnalystRouteAndSafeBoundedNoStoreReport()throws Exception{
  String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"API-110 actual HTTP acceptance uses isolated PostgreSQL");var rg=KeyPairGenerator.getInstance("RSA");rg.initialize(2048);var rsa=rg.generateKeyPair();var eg=KeyPairGenerator.getInstance("EC");eg.initialize(new java.security.spec.ECGenParameterSpec("secp256r1"));var ec=eg.generateKeyPair();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);String issuer="http://127.0.0.1:"+server.getAddress().getPort()+"/realms/offline";server.createContext("/",x->{byte[] body=EventCodec.JSON.writeValueAsBytes(Map.of("keys",List.of(new RSAKey.Builder((RSAPublicKey)rsa.getPublic()).keyID("synthetic").algorithm(JWSAlgorithm.RS256).keyUse(KeyUse.SIGNATURE).build().toJSONObject())));x.getResponseHeaders().set("Content-Type","application/json");x.sendResponseHeaders(200,body.length);x.getResponseBody().write(body);x.close();});server.start();var props=new HashMap<String,Object>();props.put("APP_ENV","test");props.put("NIGSON_SECURITY_ENABLED","true");props.put("NIGSON_PRODUCT_PHASE","4");props.put("NIGSON_EVENTS_ENABLED","false");props.put("NIGSON_JDBC_URL",url+"?currentSchema=experience");props.put("NIGSON_DB_USER","nigson_experience_app");props.put("NIGSON_DB_PASSWORD","mock-experience-runtime");props.put("NIGSON_OIDC_ISSUER",issuer);props.put("NIGSON_OIDC_JWKS",issuer+"/protocol/openid-connect/certs");props.put("NIGSON_PRIVATE_PEER_CIDRS","127.0.0.1/32");props.put("NIGSON_ACTOR_PUBLIC_KEYS",EventCodec.JSON.writeValueAsString(Map.of("active",Base64.getEncoder().encodeToString(ec.getPublic().getEncoded()))));props.put("NIGSON_DISTRIBUTOR_REQUIRED_DOCUMENT_TYPES","CERTIFICATE,IDENTITY");props.put("NIGSON_DISTRIBUTOR_RECIPIENT_GROUP","synthetic-distributor-review");props.put("NIGSON_DISTRIBUTOR_COMMERCE_MODE","mock");byte[] ph=new byte[32],pc=new byte[32],ic=new byte[32];Arrays.fill(ph,(byte)7);Arrays.fill(pc,(byte)8);Arrays.fill(ic,(byte)9);props.put("NIGSON_MESSAGING_INBOUND_ENABLED","true");props.put("NIGSON_LEAD_RECIPIENT_GROUP","synthetic-sales-triage");props.put("NIGSON_PHONE_CIPHER_REVISION","synthetic");props.put("NIGSON_PHONE_HASH_KEY_VERSION","1");props.put("NIGSON_PHONE_LOCAL_HASH_KEY",Base64.getEncoder().encodeToString(ph));props.put("NIGSON_PHONE_LOCAL_CIPHER_KEY",Base64.getEncoder().encodeToString(pc));props.put("NIGSON_INBOUND_LOCAL_CIPHER_KEY",Base64.getEncoder().encodeToString(ic));props.put("NIGSON_INBOUND_RETENTION_DAYS","30");props.put("NIGSON_TWILIO_ACCOUNT_SID","AC0123456789abcdef0123456789abcdef");props.put("NIGSON_TWILIO_AUTH_TOKEN","synthetic-auth-token-that-is-long-enough-never-live");props.put("NIGSON_TWILIO_WHATSAPP_FROM","whatsapp:+2348031234567");props.put("NIGSON_TWILIO_WHATSAPP_PUBLIC_URL","https://callbacks.synthetic.invalid/api/v1/webhooks/notifications/twilio/whatsapp");props.put("server.port","0");props.put("logging.level.root","WARN");
  try(var app=new SpringApplicationBuilder(ExperienceApplication.class).properties(props).run();var http=HttpClient.newHttpClient()){
   String base="http://127.0.0.1:"+((WebServerApplicationContext)app).getWebServer().getPort(),path="/api/v1/staff/reports/engagement",scope="report.read_WITH_SIGNED_ANALYST";JdbcTemplate jdbc=app.getBean(JdbcTemplate.class);Instant reportFrom=Instant.parse("2045-01-01T05:00:00Z"),reportTo=Instant.parse("2045-01-02T05:00:00Z");jdbc.update("INSERT INTO experience.lead(id,created_at,created_by,updated_by,type,name,email,subject,message,status,source) VALUES (?,? ,'synthetic','synthetic','CONTACT','Private HTTP Name','private-http@example.invalid','Private HTTP subject','Private HTTP message','NEW','HTTP_TEST')",UUID.randomUUID(),java.sql.Timestamp.from(reportFrom));jdbc.update("INSERT INTO experience.lead(id,created_at,created_by,updated_by,type,name,email,subject,message,status,source) VALUES (?,? ,'synthetic','synthetic','CONTACT','End Boundary','end@example.invalid','End Boundary','Outside','NEW','HTTP_TEST')",UUID.randomUUID(),java.sql.Timestamp.from(reportTo));long auditBefore=jdbc.queryForObject("SELECT count(*) FROM experience.audit_record WHERE action='REPORT_READ'",Long.class);String analyst=actor(ec,issuer,UUID.randomUUID(),"ANALYST",scope,path),sales=actor(ec,issuer,UUID.randomUUID(),"SALES",scope,path),orgAnalyst=actor(ec,issuer,UUID.randomUUID(),"ANALYST",scope,path,UUID.randomUUID(),""),token=workload(rsa,issuer,"nigson-commerce",scope);assertThat(send(http,base+path+"?from=2045-01-01T00%3A00%3A00Z&to=2045-01-02T00%3A00%3A00Z",null,null).statusCode()).isEqualTo(401);assertThat(send(http,base+path+"?from=2045-01-01T00%3A00%3A00Z&to=2045-01-02T00%3A00%3A00Z",workload(rsa,issuer,"wrong-client",scope),analyst).statusCode()).isEqualTo(401);assertThat(send(http,base+path+"?from=2045-01-01T00%3A00%3A00Z&to=2045-01-02T00%3A00%3A00Z",token,sales).statusCode()).isEqualTo(403);assertThat(send(http,base+path+"?from=2045-01-01T00%3A00%3A00Z&to=2045-01-02T00%3A00%3A00Z",token,orgAnalyst).statusCode()).isEqualTo(403);
   String query="?from=2045-01-01T00%3A00%3A00-05%3A00&to=2045-01-02T00%3A00%3A00-05%3A00";var ok=send(http,base+path+query,token,analyst);assertThat(ok.statusCode()).withFailMessage(ok.body()).isEqualTo(200);assertThat(ok.headers().firstValue("Cache-Control")).hasValue("no-store");var dto=EventCodec.JSON.readTree(ok.body());assertThat(dto.propertyNames()).containsExactlyInAnyOrder("leadsByState","applicationsByState","reviewsByState","subscriptions","campaigns");assertThat(dto.path("leadsByState").path("NEW").asLong()).isEqualTo(1);assertThat(ok.body()).doesNotContain("Private HTTP Name","private-http@example.invalid","Private HTTP subject","Private HTTP message","End Boundary","Outside");assertThat(send(http,base+path+"?from=2045-01-02T00%3A00%3A00Z&to=2045-01-01T00%3A00%3A00Z",token,analyst).statusCode()).isEqualTo(400);assertThat(send(http,base+path+"?from=2045-01-01T00%3A00%3A00Z&to=2046-01-03T00%3A00%3A00Z",token,analyst).statusCode()).isEqualTo(400);assertThat(send(http,base+path+"?from=2045-01-01T00%3A00%3A00Z&to=2045-01-02T00%3A00%3A00Z&unexpected=x",token,analyst).statusCode()).isEqualTo(400);assertThat(send(http,base+path+"?from=2045-01-01T00%3A00%3A00Z&from=2045-01-01T00%3A00%3A00Z&to=2045-01-02T00%3A00%3A00Z",token,analyst).statusCode()).isEqualTo(400);assertThat(send(http,base+path+query,token,actor(ec,issuer,UUID.randomUUID(),"ANALYST",scope,path,"{}"),"{}").statusCode()).isEqualTo(400);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.audit_record WHERE action='REPORT_READ'",Long.class)).isEqualTo(auditBefore+1);var replay=send(http,base+path+query,token,analyst);assertThat(replay.statusCode()).isEqualTo(200);assertThat(replay.body()).isEqualTo(ok.body());assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.audit_record WHERE action='REPORT_READ'",Long.class)).isEqualTo(auditBefore+2);
  }finally{server.stop(0);}
 }
 private static String workload(KeyPair rsa,String issuer,String client,String scope)throws Exception{var jwt=new SignedJWT(new JWSHeader.Builder(JWSAlgorithm.RS256).keyID("synthetic").build(),new JWTClaimsSet.Builder().issuer(issuer).subject("synthetic-workload").audience("nigson-experience").claim("typ","Bearer").claim("client_id",client).claim("azp",client).claim("scope",scope).issueTime(Date.from(Instant.now())).expirationTime(Date.from(Instant.now().plusSeconds(120))).build());jwt.sign(new RSASSASigner((RSAPrivateKey)rsa.getPrivate()));return jwt.serialize();}
 private static String actor(KeyPair ec,String issuer,UUID party,String role,String scope,String path)throws Exception{return actor(ec,issuer,party,role,scope,path,"");}
 private static String actor(KeyPair ec,String issuer,UUID party,String role,String scope,String path,String body)throws Exception{return actor(ec,issuer,party,role,scope,path,null,body);}
 private static String actor(KeyPair ec,String issuer,UUID party,String role,String scope,String path,UUID organization,String body)throws Exception{var a=new ActorAssertion.Actor(party,issuer,"synthetic-analyst",organization,Set.of(role),Set.of(scope),null);var b=new ActorAssertion.Binding("experience",scope,"GET",path,CORRELATION,ActorAssertion.Binding.bodyHash(body.getBytes(StandardCharsets.UTF_8)));var jwt=new SignedJWT(new JWSHeader.Builder(JWSAlgorithm.ES256).keyID("active").type(new JOSEObjectType("nigson-actor+jwt")).build(),ActorAssertion.claims(a,b,Instant.now()));jwt.sign(new ECDSASigner((ECPrivateKey)ec.getPrivate()));return jwt.serialize();}
 private static HttpResponse<String> send(HttpClient http,String url,String workload,String actor)throws Exception{return send(http,url,workload,actor,null);}
 private static HttpResponse<String> send(HttpClient http,String url,String workload,String actor,String body)throws Exception{var b=HttpRequest.newBuilder(URI.create(url)).timeout(Duration.ofSeconds(10)).header("X-Correlation-ID",CORRELATION.toString());if(workload!=null)b.header("Authorization","Bearer "+workload);if(actor!=null)b.header("X-Nigson-Actor",actor);if(body==null)b.GET();else b.header("Content-Type","application/json").method("GET",HttpRequest.BodyPublishers.ofString(body));return http.send(b.build(),HttpResponse.BodyHandlers.ofString());}
}
